-- -------------------------------------------------------------
INSERT INTO tac_consultations (acd_id, prt_id, cst_channel, cst_status, cst_note)
SELECT @academy_id, s.prt_id, 'RECURRING', 'OPEN', '[학생: 강병찬] TPI 정기 학부모 상담 (2달 1회) — imported from spreadsheet
커리큘럼: GPA 관리
담당강사: 김태윤'
