-- -------------------------------------------------------------
-- 8. Verification
-- -------------------------------------------------------------
SELECT '— v2 verification —' AS section;
SELECT COUNT(*) AS total_students FROM tac_students WHERE acd_id=@academy_id;
SELECT std_lifecycle_status, COUNT(*) FROM tac_students WHERE acd_id=@academy_id GROUP BY 1;
SELECT COUNT(*) AS parent_rows FROM tac_parents WHERE acd_id=@academy_id;
SELECT COUNT(*) AS consultations FROM tac_consultations WHERE acd_id=@academy_id;
SELECT COUNT(*) AS map_scores FROM tac_map_scores;
SELECT prt_id, COUNT(*) AS siblings FROM tac_students WHERE acd_id=@academy_id
 GROUP BY prt_id HAVING COUNT(*)>1 ORDER BY siblings DESC LIMIT 10;
SELECT '✅ v2 seed complete' AS result;
